import{_ as a,o as r,c as t,a4 as o}from"./chunks/framework.CSpBcIj4.js";const f=JSON.parse('{"title":"关于苍蓝星图鉴","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hans/others/"}],["meta",{"property":"og:title","content":"关于苍蓝星图鉴 | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Monster Hunter reference data and armor builds for Wilds, Rise with Sunbreak, and World with Iceborne."}]]},"headers":[],"relativePath":"zh-hans/others/index.md","filePath":"zh-hans/others/index.md"}'),n={name:"zh-hans/others/index.md"};function h(i,e,s,l,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="关于苍蓝星图鉴" tabindex="-1">关于苍蓝星图鉴 <a class="header-anchor" href="#关于苍蓝星图鉴" aria-label="Permalink to &quot;关于苍蓝星图鉴&quot;">​</a></h1><h2 id="这是什么应用" tabindex="-1">这是什么应用？ <a class="header-anchor" href="#这是什么应用" aria-label="Permalink to &quot;这是什么应用？&quot;">​</a></h2><p>苍蓝星图鉴（Sapphire Star Codex）是一个查怪物猎人资料、找配装的应用，由 <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a> 的开发者独立制作。这是一个非商业项目，没有广告，也不用付费。</p><h2 id="怎么帮忙完善图鉴" tabindex="-1">怎么帮忙完善图鉴？ <a class="header-anchor" href="#怎么帮忙完善图鉴" aria-label="Permalink to &quot;怎么帮忙完善图鉴？&quot;">​</a></h2><p>可以帮忙核对资料、检查翻译，或者把网站分享给一起玩的朋友。</p><p>目前还没开放反馈入口，等应用上架后会补上。如果你发现资料有问题，记下游戏和扩展包、怪物或装备的名字、使用的语言，以及哪里不对，再附上出处或操作步骤。发截图前，记得遮住个人信息。</p><p>也可以到<a href="https://github.com/eurekaffeine" target="_blank" rel="noreferrer">开发者主页</a>看看后续的联系方式。</p><h2 id="资料和图片从哪来" tabindex="-1">资料和图片从哪来？ <a class="header-anchor" href="#资料和图片从哪来" aria-label="Permalink to &quot;资料和图片从哪来？&quot;">​</a></h2><p>资料按游戏分别整理，来源包括 <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>、<a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> 和游戏文件，也会参考社区资料核对。部分内容可能还不完整，或者有错误，我们会继续补充和修正。</p><h2 id="版权与声明" tabindex="-1">版权与声明 <a class="header-anchor" href="#版权与声明" aria-label="Permalink to &quot;版权与声明&quot;">​</a></h2><p>苍蓝星图鉴是非商业的玩家自制应用，与 CAPCOM 没有关联，也没有得到其认可或支持。Monster Hunter 的名称、设计、官方图标和游戏数据归 CAPCOM Co., Ltd. 所有。如果权利人要求移除相关内容，我们会配合处理。</p><p>网站沿用了 Pocket Gallery 中采用 MIT 许可的 VitePress 组件。这个许可只适用于代码，不包括游戏图片和数据。</p>',12)])])}const u=a(n,[["render",h]]);export{f as __pageData,u as default};
